const taigaAuth = { Authorization: `Bearer ${$env.TAIGA_TOKEN}` };
const tag = $env.RELEASE_VERSION;
const stories = await this.helpers.httpRequest({ method: 'GET', url: `${$env.TAIGA_URL}/api/v1/userstories`, qs: { project: $env.TAIGA_PROJECT_ID, tags: tag }, headers: taigaAuth, json: true });
const tasks = await this.helpers.httpRequest({ method: 'GET', url: `${$env.TAIGA_URL}/api/v1/tasks`, qs: { project: $env.TAIGA_PROJECT_ID, tags: tag }, headers: taigaAuth, json: true });
return [
  ...stories.map(s => ({ json: { ...s, _taigaType: 'userstory' } })),
  ...tasks.map(t => ({ json: { ...t, _taigaType: 'task' } })),
];

const items = $input.all().map(i => i.json);
const stories = items.filter(t => t._taigaType === 'userstory');
const tasks = items.filter(t => t._taigaType === 'task');
const open = stories.filter(t => !t.is_closed).length;
const merged = stories.filter(t => t.is_closed).length;
const tasksOpen = tasks.filter(t => !t.is_closed).length;
const tasksClosed = tasks.filter(t => t.is_closed).length;
return [{json: {
  version: $env.RELEASE_VERSION,
  stories_total: stories.length,
  stories_open: open,
  stories_merged: merged,
  tasks_open: tasksOpen,
  tasks_closed: tasksClosed,
  dag_paused: $env.DAG_PAUSED ?? false,
  summary: `${merged}/${stories.length} stories merged, ${tasksOpen} tasks open`
}}];
